#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();
    let cfg = Config::load(&cli)?;
    let engine = Arc::new(Engine::open(&cfg.data_dir)?);
    tracing::info!(port = cfg.port, "starting tinykv");
    Server::new(cfg, engine).run().await
}

pub async fn run(self) -> Result<()> {
    let listener = TcpListener::bind(("0.0.0.0", self.cfg.port)).await?;
    loop {
        let permit = self.limiter.clone().acquire_owned().await?;
        let (sock, peer) = listener.accept().await?;
        let router = self.router.clone();
        tokio::spawn(Conn::new(sock, peer, router).serve(permit));
    }
}

pub async fn serve(mut self, _permit: OwnedSemaphorePermit) {
    while let Some(frame) = self.framed.next().await {
        let resp = match Command::try_from(frame) {
            Ok(cmd) => self.router.dispatch(cmd).await,
            Err(e) => Response::Error(e.to_string()),
        };
        let _ = self.framed.send(resp).await;
    }
}

pub async fn dispatch(&self, cmd: Command) -> Response {
    match self.handlers.get(&cmd.op()) {
        Some(h) => h.handle(cmd).await.unwrap_or_else(Response::from),
        None => Response::Error("unknown command".into()),
    }
}

#[async_trait]
pub trait Handler: Send + Sync {
    async fn handle(&self, cmd: Command) -> Result<Response>;
}

async fn handle(&self, cmd: Command) -> Result<Response> {
    let Command::Get { key } = cmd else { bail!("bad cmd") };
    Ok(match self.engine.get(&key) {
        Some(v) => Response::Bulk(v),
        None => Response::Nil,
    })
}

async fn handle(&self, cmd: Command) -> Result<Response> {
    let Command::Put { key, val } = cmd else { bail!("bad cmd") };
    self.engine.put(key, val)?;
    Ok(Response::Ok)
}

pub fn put(&self, key: Bytes, val: Bytes) -> Result<()> {
    let mut wal = self.wal.lock();
    wal.append(&Record::Put { key: &key, val: &val })?;
    self.mem.load().insert(key, val);
    Ok(())
}

pub fn append(&mut self, rec: &Record) -> Result<()> {
    let buf = rec.encode();
    self.file.write_u32::<LE>(buf.len() as u32)?;
    self.file.write_u32::<LE>(crc32fast::hash(&buf))?;
    self.file.write_all(&buf)?;
    self.maybe_sync()
}
